// src/data/dailies.ts
var START = dailies_generated_default.start;
var DAILIES = dailies_generated_default.levels;
var toUtc = (day) => {
  const [y, m, d] = day.split("-").map(Number);
  return Date.UTC(y, m - 1, d);
};
function addDays(day, days) {
  return new Date(toUtc(day) + days * 864e5).toISOString().slice(0, 10);
}
function dailyLevel(day) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) return null;
  const index = Math.round((toUtc(day) - toUtc(START)) / 864e5);
  return DAILIES[index] ?? null;
}

