// src/data/levels.ts
var LEVELS = [...TUTORIAL, ...levels_generated_default.levels];
var LEVEL_IDS = LEVELS.map((level) => level.id);
function levelById(id) {
  return LEVELS.find((level) => level.id === id);
}
function levelNumber(id) {
  return LEVELS.findIndex((level) => level.id === id) + 1;
}

// src/server/scores.ts
var JUDGE_VERSION = `${BUNDLED_MODEL.trainedAt}+grammar1`;
function scoreRun(level, actions) {
  const run2 = parseRun(actions);
  if (typeof run2 === "string") return run2;
  const { state, error } = replayRun(level, run2, builtinJudge);
  if (error) return error;
  if (state.phase !== "won" && state.phase !== "lost") return "the game isn't finished";
  const won = state.phase === "won";
  return {
    won,
    score: state.lastResult?.total ?? 0,
    stars: won ? state.lastResult.stars : 0,
    submits: state.submitsUsed
  };
}
function scoreDaily(day, actions, now) {
  const level = dailyLevel(day);
  if (!level) return "there is no daily puzzle that day";
  const today = now.toISOString().slice(0, 10);
  if (day < addDays(today, -1) || day > addDays(today, 1)) return "that daily puzzle is closed";
  return scoreRun(level, actions);
}
function scoreLevel(levelId, actions, tuning = {}) {
  const level = typeof levelId === "string" ? levelById(levelId) : void 0;
  if (!level) return "there is no such level";
  const scored = scoreRun(tuneLevel(level, levelNumber(level.id), parseTuning(tuning)), actions);
  if (typeof scored === "string") return scored;
  return scored.won ? scored : "the built-in judge didn't pass this board";
}
function sampleRun(level) {
  return [...playLevel(level, "careful").moves, { type: "submit" }];
}
export {
  JUDGE_VERSION,
  dailyLevel,
  levelById,
  sampleRun,
  scoreDaily,
  scoreLevel,
  scoreRun
};
